$(() => {
  const 一周 = ['周一', '周二', '周三', '周四', '周五', '周六', '周日'];
  const 默认推进分钟 = 30;

  function 推进时间(时间: { 周几: string; 小时: number; 分钟: number } | undefined, 分钟增量: number): boolean {
    if (!时间) return false;
    const 总分钟 = Number(时间.小时 || 0) * 60 + Number(时间.分钟 || 0) + 分钟增量;
    if (!Number.isFinite(总分钟) || 总分钟 < 0) return false;
    const 进位小时 = Math.floor(总分钟 / 60);
    时间.分钟 = 总分钟 % 60;
    时间.小时 = 进位小时 % 24;
    const 跨天 = Math.floor(进位小时 / 24);
    if (跨天 > 0 && 一周.includes(时间.周几)) {
      时间.周几 = 一周[(一周.indexOf(时间.周几) + 跨天) % 7];
    }
    return true;
  }

  eventOn(tavern_events.GENERATION_ENDED, async () => {
    try {
      await waitGlobalInitialized('Mvu');
      if (Mvu.isDuringExtraAnalysis()) return;

      const 最新 = getChatMessages(-1)[0];
      if (!最新 || 最新.role !== 'assistant') return;
      if (/<update(?:variable)?>/i.test(最新.message ?? '')) return;

      const data = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
      const 时间 = data?.stat_data?.时间;
      if (!时间) return;

      if (推进时间(时间, 默认推进分钟)) {
        await Mvu.replaceMvuData(data, { type: 'message', message_id: 'latest' });
      }
    } catch (error) {
      console.error('[星晚·时间推进兜底]', error);
    }
  });
});
